  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://estate.local/schemas/router_family_entry.schema.json",
  "title": "RouterFamilyEntry",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "family_id",
    "model_id",
    "prices",
    "duels",
    "totals",
    "quality_gate",
    "provenance"
  ],
  "properties": {
    "family_id": { "type": "string", "minLength": 1 },
    "model_id": { "type": "string", "minLength": 1 },
    "prices": {
      "type": "object",
